import * as fs from "node:fs";
import { createRequire } from "node:module";
import * as path from "node:path";

/**
 * Resolve the bin/ directory inside the installed @microsoft/mxc-sdk package.
 * Returns the arch-specific subdirectory (x64 or arm64) if available.
 */
function resolveSdkBinDir(): string | null {
  try {
    const require = createRequire(import.meta.url);
    const sdkPkgPath = require.resolve("@microsoft/mxc-sdk/package.json");
    const sdkRoot = path.dirname(sdkPkgPath);
    const arch = process.arch === "arm64" ? "arm64" : "x64";
    const archBin = path.join(sdkRoot, "bin", arch);
    if (fs.existsSync(archBin)) {
      return archBin;
    }
    // Fallback to flat bin/ if no arch subdirectory
    const flatBin = path.join(sdkRoot, "bin");
    if (fs.existsSync(flatBin)) {
      return flatBin;
    }
  } catch {
    // SDK not installed; skip.
  }
  return null;
}

function buildSearchPaths(binary: string, sdkBinDir: string | null): string[] {
  return sdkBinDir ? [path.join(sdkBinDir, binary)] : [];
}

/** SDK-owned search paths for wxc-exec on Windows. */
function wxcSearchPaths(): string[] {
  return buildSearchPaths("wxc-exec.exe", resolveSdkBinDir());
}

function findBinary(searchPaths: string[]): string | null {
  for (const p of searchPaths) {
    if (fs.existsSync(p)) {
      return p;
    }
  }
  return null;
}

/**
 * Resolves the MXC executor binary path.
 * @param configOverride Optional user-configured path override.
 * @returns Absolute path to the binary.
 * @throws If the binary cannot be found.
 */
export function resolveMxcBinaryPath(configOverride?: string): string {
  if (configOverride) {
    const resolvedOverride = path.win32.isAbsolute(configOverride)
      ? configOverride
      : path.resolve(configOverride);
    if (!fs.existsSync(resolvedOverride)) {
      throw new Error(`MXC binary not found at configured path: ${configOverride}`);
    }
    return resolvedOverride;
  }

  const binaryName = "wxc-exec.exe";
  const found = findBinary(wxcSearchPaths());

  if (!found) {
    throw new Error(
      `MXC executor "${binaryName}" not found. Install @microsoft/mxc-sdk or set mxcBinaryPath in config.`,
    );
  }
  return found;
}

import { posix, win32 } from "node:path";
import { buildPluginConfigSchema, type OpenClawPluginConfigSchema } from "openclaw/plugin-sdk/core";
import {
  formatPluginConfigIssue,
  mapPluginConfigIssues,
} from "openclaw/plugin-sdk/extension-shared";
import { MAX_TIMER_TIMEOUT_SECONDS } from "openclaw/plugin-sdk/number-runtime";
import { z } from "zod";

const MXC_CONTAINMENTS = ["process", "processcontainer"] as const;
const MXC_NETWORK_MODES = ["none", "default"] as const;

type MxcContainment = (typeof MXC_CONTAINMENTS)[number];

type MxcNetworkMode = (typeof MXC_NETWORK_MODES)[number];

export type MxcConfig = {
  mxcBinaryPath?: string;
  containment: MxcContainment;
  network: MxcNetworkMode;
  timeoutSeconds: number;
  timeoutSecondsConfigured?: boolean;
  debug: boolean;
  mxcPolicyPaths?: string[];
};

const DEFAULT_CONTAINMENT: MxcContainment = "process";
const DEFAULT_NETWORK: MxcNetworkMode = "none";
const DEFAULT_TIMEOUT_SECONDS = 120;
const DEFAULT_DEBUG = false;

const nonEmptyTrimmedString = (message: string) =>
  z.string({ error: message }).trim().min(1, { error: message });

const MxcPluginConfigSchema = z.strictObject({
  mxcBinaryPath: nonEmptyTrimmedString("mxcBinaryPath must be a non-empty string")
    .describe(
      "Absolute path to the MXC executor (wxc-exec.exe). When unset, the executor is discovered from the installed @microsoft/mxc-sdk.",
    )
    .optional(),
  containment: z
    .enum(MXC_CONTAINMENTS, {
      error: `containment must be one of ${MXC_CONTAINMENTS.join(", ")}`,
    })
    .describe(
      "Windows containment mode. 'process' and 'processcontainer' currently both resolve to the Windows ProcessContainer sandbox.",
    )
    .optional(),
  network: z
    .enum(MXC_NETWORK_MODES, {
      error: `network must be one of ${MXC_NETWORK_MODES.join(", ")}`,
    })
    .describe(
      "Outbound network policy. 'none' blocks all network; 'default' allows outbound access via the internetClient capability.",
    )
    .optional(),
  timeoutSeconds: z
    .number({
      error: `timeoutSeconds must be a number between 1 and ${MAX_TIMER_TIMEOUT_SECONDS}`,
    })
    .min(1, { error: "timeoutSeconds must be a number >= 1" })
    .max(MAX_TIMER_TIMEOUT_SECONDS, {
      error: `timeoutSeconds must be a number <= ${MAX_TIMER_TIMEOUT_SECONDS}`,
    })
    .describe(
      "Per-command execution timeout in seconds. Capped to the sandbox policy baseline timeout when both are set.",
    )
    .optional(),
  debug: z
    .boolean({ error: "debug must be a boolean" })
    .describe("Forward verbose debug output from the MXC SDK launcher.")
    .optional(),
  mxcPolicyPaths: z
    .array(nonEmptyTrimmedString("mxcPolicyPaths must be an array of non-empty strings"), {
      error: "mxcPolicyPaths must be an array of non-empty strings",
    })
    .describe(
      "Absolute MXC policy file paths applied on top of the built-in sandbox baseline policy.",
    )
    .optional(),
});

export function createMxcPluginConfigSchema(): OpenClawPluginConfigSchema {
  return buildPluginConfigSchema(MxcPluginConfigSchema, {
    safeParse(value) {
      if (value === undefined) {
        return { success: true, data: undefined };
      }
      const parsed = MxcPluginConfigSchema.safeParse(value);
      if (parsed.success) {
        return { success: true, data: parsed.data };
      }
      return {
        success: false,
        error: {
          issues: mapPluginConfigIssues(parsed.error.issues),
        },
      };
    },
  });
}

export function resolveConfig(value: unknown): MxcConfig {
  if (value === undefined) {
    return {
      mxcBinaryPath: undefined,
      containment: DEFAULT_CONTAINMENT,
      network: DEFAULT_NETWORK,
      timeoutSeconds: DEFAULT_TIMEOUT_SECONDS,
      debug: DEFAULT_DEBUG,
    };
  }

  const parsed = MxcPluginConfigSchema.safeParse(value);
  if (!parsed.success) {
    const message = formatPluginConfigIssue(parsed.error.issues[0]);
    throw new Error(`Invalid mxc plugin config: ${message}`);
  }

  const config = parsed.data;
  const resolved: MxcConfig = {
    mxcBinaryPath: config.mxcBinaryPath,
    containment: config.containment ?? DEFAULT_CONTAINMENT,
    network: config.network ?? DEFAULT_NETWORK,
    timeoutSeconds: config.timeoutSeconds ?? DEFAULT_TIMEOUT_SECONDS,
    debug: config.debug ?? DEFAULT_DEBUG,
    mxcPolicyPaths: resolveMxcPolicyPaths(config.mxcPolicyPaths),
  };

  if (config.timeoutSeconds !== undefined) {
    resolved.timeoutSecondsConfigured = true;
  }

  return resolved;
}

function resolveMxcPolicyPaths(value: string[] | undefined): string[] | undefined {
  if (value === undefined) {
    return undefined;
  }
  return value.map((entry, index) => {
    if (!isAbsolutePath(entry)) {
      throw new Error(
        `Invalid mxc plugin config: mxcPolicyPaths[${index}] must be an absolute path`,
      );
    }
    return entry;
  });
}

function isAbsolutePath(value: string): boolean {
  return win32.isAbsolute(value) || posix.isAbsolute(value);
}

import path from "node:path";
import {
  isPathInside,
  removePathWithinRoot,
  root as fsRoot,
} from "openclaw/plugin-sdk/file-access-runtime";
import {
  createWritableRenameTargetResolver,
  type SandboxBackendHandle,
  type SandboxFsBridge,
  type SandboxFsStat,
  type SandboxResolvedPath,
} from "openclaw/plugin-sdk/sandbox";
import { FsSafeError } from "openclaw/plugin-sdk/security-runtime";
import {
  resolveMxcReadOnlySkillMounts,
  type MxcReadOnlySkillMount,
} from "./workspace-skill-mounts.js";

type MxcFsBridgeContext = Parameters<
  NonNullable<SandboxBackendHandle["createFsBridge"]>
>[0]["sandbox"];

type MxcFsMount = {
  hostRoot: string;
  containerRoot: string;
  writable: boolean;
};

type ResolvedMxcPath = SandboxResolvedPath & {
  hostPath: string;
  mount: MxcFsMount;
  mountRelativePath: string;
  writable: boolean;
};

export function createMxcFsBridge(params: { sandbox: MxcFsBridgeContext }): SandboxFsBridge {
  return new MxcFsBridge(params.sandbox);
}

class MxcFsBridge implements SandboxFsBridge {
  // These must be assigned in the constructor body, not as field initializers.
  // Plugin sources load through jiti, which evaluates field initializers before
  // it assigns constructor parameter properties, so `this.sandbox` would still
  // be undefined here and provisioning would crash reading containerWorkdir.
  private readonly defaultContainerRoot: string;

  private readonly protectedSkillMounts: readonly MxcFsMount[];

  private readonly workspaceMounts: readonly MxcFsMount[];

  private readonly resolveRenameTargets = createWritableRenameTargetResolver(
    (target) => this.resolveTarget(target),
    (target, action) => this.ensureWritable(target, action),
  );

  constructor(private readonly sandbox: MxcFsBridgeContext) {
    this.defaultContainerRoot = path.resolve(sandbox.containerWorkdir);
    this.protectedSkillMounts = resolveMxcProtectedSkillMounts(sandbox);
    this.workspaceMounts = resolveWorkspaceMounts(sandbox);
  }

  resolvePath(params: { filePath: string; cwd?: string }): SandboxResolvedPath {
    const target = this.resolveTarget(params);
    return {
      hostPath: target.hostPath,
      relativePath: target.relativePath,
      containerPath: target.containerPath,
    };
  }

  async readFile(params: { filePath: string; cwd?: string; maxBytes?: number }): Promise<Buffer> {
    const target = this.resolveTarget(params);
    return (await (
      await fsRoot(target.mount.hostRoot)
    ).readBytes(target.mountRelativePath, {
      hardlinks: "reject",
      ...(params.maxBytes === undefined ? {} : { maxBytes: params.maxBytes }),
    })) as Buffer;
  }

  async writeFile(params: {
    filePath: string;
    cwd?: string;
    data: Buffer | string;
    encoding?: BufferEncoding;
    mkdir?: boolean;
  }): Promise<void> {
    const target = this.resolveTarget(params);
    this.ensureWritable(target, "write files");
    const buffer = Buffer.isBuffer(params.data)
      ? params.data
      : Buffer.from(params.data, params.encoding ?? "utf8");
    await (
      await fsRoot(target.mount.hostRoot)
    ).write(target.mountRelativePath, buffer, {
      mkdir: params.mkdir !== false,
    });
  }

  async createFileExclusive(params: {
    filePath: string;
    cwd?: string;
    data: Buffer | string;
    encoding?: BufferEncoding;
    mkdir?: boolean;
  }): Promise<"created" | "exists"> {
    const target = this.resolveTarget(params);
    this.ensureWritable(target, "create files");
    const buffer = Buffer.isBuffer(params.data)
      ? params.data
      : Buffer.from(params.data, params.encoding ?? "utf8");
    try {
      await (
        await fsRoot(target.mount.hostRoot)
      ).create(target.mountRelativePath, buffer, {
        mkdir: params.mkdir !== false,
      });
      return "created";
    } catch (error) {
      if (error instanceof FsSafeError && error.code === "already-exists") {
        return "exists";
      }
      throw error;
    }
  }

  async mkdirp(params: { filePath: string; cwd?: string }): Promise<void> {
    const target = this.resolveTarget(params);
    this.ensureWritable(target, "create directories");
    if (target.mountRelativePath.length === 0) {
      return;
    }
    await (await fsRoot(target.mount.hostRoot)).mkdir(target.mountRelativePath);
  }

  async remove(params: {
    filePath: string;
    cwd?: string;
    recursive?: boolean;
    force?: boolean;
  }): Promise<void> {
    const target = this.resolveTarget(params);
    this.ensureWritable(target, "remove files");
    await removePathWithinRoot({
      rootDir: target.mount.hostRoot,
      relativePath: target.mountRelativePath,
      recursive: params.recursive,
      force: params.force ?? false,
    });
  }

  async rename(params: { from: string; to: string; cwd?: string }): Promise<void> {
    const { from: source, to: target } = this.resolveRenameTargets(params);
    if (!isSameMountRoot(source.mount.hostRoot, target.mount.hostRoot)) {
      throw new Error(
        `Sandbox rename must stay within the same mounted root: ${source.containerPath} -> ${target.containerPath}`,
      );
    }

    const root = await fsRoot(source.mount.hostRoot);
    const targetParent = resolveRelativeParentPath(target.mountRelativePath);
    if (targetParent) {
      await root.mkdir(targetParent);
    }
    await root.move(source.mountRelativePath, target.mountRelativePath, { overwrite: true });
  }

  async stat(params: { filePath: string; cwd?: string }): Promise<SandboxFsStat | null> {
    const target = this.resolveTarget(params);
    const root = await fsRoot(target.mount.hostRoot);
    if (!(await root.exists(target.mountRelativePath))) {
      return null;
    }

    const stats = await root.stat(target.mountRelativePath);
    return {
      type: stats.isDirectory ? "directory" : stats.isFile ? "file" : "other",
      size: stats.size,
      mtimeMs: stats.mtimeMs,
    };
  }

  private resolveTarget(params: { filePath: string; cwd?: string }): ResolvedMxcPath {
    const input = params.filePath.trim();
    const cwd = params.cwd?.trim() ? path.resolve(params.cwd) : this.defaultContainerRoot;
    const containerPath = path.isAbsolute(input) ? path.resolve(input) : path.resolve(cwd, input);

    return (
      this.resolveMountedTarget(containerPath, this.protectedSkillMounts) ??
      this.resolveMountedTarget(containerPath, this.workspaceMounts) ??
      this.throwSandboxRootEscape(params.filePath)
    );
  }

  private resolveMountedTarget(
    containerPath: string,
    mounts: readonly MxcFsMount[],
  ): ResolvedMxcPath | null {
    for (const mount of mounts) {
      if (!isPathInside(mount.containerRoot, containerPath)) {
        continue;
      }

      const mountRelativePath = path.relative(mount.containerRoot, containerPath);
      return {
        hostPath: path.join(mount.hostRoot, mountRelativePath),
        relativePath: mountRelativePath,
        containerPath,
        mount,
        mountRelativePath,
        writable: mount.writable,
      };
    }
    return null;
  }

  private throwSandboxRootEscape(filePath: string): never {
    const allowedRoots = [
      ...new Set(this.workspaceMounts.map((mount) => mount.containerRoot)),
    ].join(", ");
    throw new Error(
      `Path escapes sandbox root (${allowedRoots}; container root ${this.sandbox.containerWorkdir}): ${filePath}. Use a path under ${this.sandbox.containerWorkdir}\\ instead.`,
    );
  }

  private ensureWritable(target: ResolvedMxcPath, action: string): void {
    if (!target.writable) {
      throw new Error(`Sandbox path is read-only; cannot ${action}: ${target.containerPath}`);
    }
  }
}

function resolveWorkspaceMounts(sandbox: MxcFsBridgeContext): readonly MxcFsMount[] {
  const containerRoot = path.resolve(sandbox.containerWorkdir);
  const workspaceDir = path.resolve(sandbox.workspaceDir);
  const agentWorkspaceDir = path.resolve(sandbox.agentWorkspaceDir);
  const mounts: MxcFsMount[] =
    sandbox.workspaceAccess === "rw"
      ? [
          {
            hostRoot: agentWorkspaceDir,
            containerRoot,
            writable: true,
          },
        ]
      : [
          {
            hostRoot: workspaceDir,
            containerRoot,
            writable: false,
          },
        ];

  if (
    sandbox.workspaceAccess === "ro" &&
    normalizePathForComparison(agentWorkspaceDir) !== normalizePathForComparison(workspaceDir)
  ) {
    mounts.push({
      hostRoot: agentWorkspaceDir,
      containerRoot: agentWorkspaceDir,
      writable: false,
    });
  }

  return dedupeAndSortMounts(mounts);
}

function resolveMxcProtectedSkillMounts(sandbox: MxcFsBridgeContext): readonly MxcFsMount[] {
  return dedupeAndSortMounts(
    resolveMxcReadOnlySkillMounts({
      agentWorkspaceDir: sandbox.agentWorkspaceDir,
      skillsWorkspaceDir: sandbox.skillsWorkspaceDir,
      workdir: sandbox.containerWorkdir,
      workspaceAccess: sandbox.workspaceAccess,
    }).map(normalizeMxcProtectedSkillMount),
  );
}

function normalizeMxcProtectedSkillMount(mount: MxcReadOnlySkillMount): MxcFsMount {
  return {
    hostRoot: path.resolve(mount.hostPath),
    containerRoot: path.resolve(mount.containerPath),
    writable: false,
  };
}

function dedupeAndSortMounts(mounts: readonly MxcFsMount[]): readonly MxcFsMount[] {
  const deduped = new Map<string, MxcFsMount>();
  for (const mount of mounts) {
    const key = `${normalizePathForComparison(mount.hostRoot)}::${normalizePathForComparison(
      mount.containerRoot,
    )}`;
    if (!deduped.has(key)) {
      deduped.set(key, mount);
    }
  }
  return [...deduped.values()].toSorted((left, right) => {
    const lengthDiff = right.containerRoot.length - left.containerRoot.length;
    if (lengthDiff !== 0) {
      return lengthDiff;
    }
    return right.hostRoot.length - left.hostRoot.length;
  });
}

function resolveRelativeParentPath(relativePath: string): string | null {
  const parent = path.dirname(relativePath);
  return parent === "." || parent === "" ? null : parent;
}

function isSameMountRoot(first: string, second: string): boolean {
  return normalizePathForComparison(first) === normalizePathForComparison(second);
}

function normalizePathForComparison(value: string): string {
  const resolved = path.resolve(value);
  return process.platform === "win32" ? resolved.toLowerCase() : resolved;
}

import { createHash } from "node:crypto";
import type { CreateSandboxBackendParams, SandboxBackendHandle } from "openclaw/plugin-sdk/sandbox";
import type { MxcConfig } from "./config.js";
import { createMxcSandboxBackendHandle } from "./mxc-backend.js";

function sanitizeRuntimeId(value: string): string {
  if (/:workspace:[a-f0-9]{32}$/i.test(value.trim())) {
    const hash = createHash("sha256").update(value).digest("hex").slice(0, 32);
    return `openclaw-mxc-workspace-${hash}`;
  }
  const slug = value
    .toLowerCase()
    .replace(/[^a-z0-9_.-]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 48);
  const hash = createHash("sha256").update(value).digest("hex").slice(0, 8);
  return `openclaw-mxc-${slug || "sandbox"}-${hash}`;
}

/** Factory function called by OpenClaw when sandbox.backend=mxc. */
export function createMxcSandboxBackendFactory(config: MxcConfig) {
  return async function createMxcSandboxBackend(
    params: CreateSandboxBackendParams,
  ): Promise<SandboxBackendHandle> {
    if ((params.cfg.docker.binds?.length ?? 0) > 0) {
      throw new Error("MXC sandbox backend does not support sandbox.docker.binds.");
    }
    const runtimeId = sanitizeRuntimeId(params.scopeKey);
    return createMxcSandboxBackendHandle({
      config,
      runtimeId,
      workdir: params.workspaceDir,
      agentWorkspaceDir: params.agentWorkspaceDir,
      ...(params.skillsWorkspaceDir ? { skillsWorkspaceDir: params.skillsWorkspaceDir } : {}),
      workspaceAccess: params.cfg.workspaceAccess,
    });
  };
}

import { randomBytes } from "node:crypto";
import { mkdtempSync, realpathSync, rmSync, statSync, writeFileSync } from "node:fs";
import path from "node:path";
import type { ContainerConfig } from "@microsoft/mxc-sdk";
import { isPathInside } from "openclaw/plugin-sdk/file-access-runtime";
import { runCommandBuffered } from "openclaw/plugin-sdk/process-runtime";
