type MxcLauncherOptions = {
  debug: boolean;
  executablePath?: string;
  usePty?: boolean;
};

type MxcExecFinalizeToken = {
  payloadDir: string;
  sandboxTempDir?: string;
};

// MXC containers are ephemeral (lifecycle.destroyOnExit=true) and named per invocation.
// Keep the runtimeId as the stable handle identifier (used for logs + SDK tracking) and
// derive a fresh per-call containerId from it so parallel spawns cannot collide on
// backend-specific runtime names.
const CONTAINER_ID_MAX_LEN = 80;
function uniqueContainerId(runtimeId: string): string {
  const suffix = randomBytes(4).toString("hex");
  const base =
    runtimeId.length + suffix.length + 1 > CONTAINER_ID_MAX_LEN
      ? runtimeId.slice(0, CONTAINER_ID_MAX_LEN - suffix.length - 1)
      : runtimeId;
  return `${base}-${suffix}`;
}

function createLauncherPayloadFile(
  payloadJson: string,
): MxcExecFinalizeToken & { payloadFile: string } {
  const payloadDir = mkdtempSync(
    path.join(resolvePreferredOpenClawTmpDir(), "openclaw-mxc-payload-"),
  );
  const payloadFile = path.join(payloadDir, "payload.json");
  try {
    writeFileSync(payloadFile, payloadJson, { flag: "wx", mode: 0o600 });
  } catch (err) {
    rmSync(payloadDir, { force: true, recursive: true });
    throw err;
  }
  return { payloadDir, payloadFile };
}

function cleanupLauncherPayloadFile(token: unknown): void {
  if (
    token &&
    typeof token === "object" &&
    "payloadDir" in token &&
    typeof token.payloadDir === "string"
  ) {
    rmSync(token.payloadDir, { force: true, recursive: true });
    if ("sandboxTempDir" in token && typeof token.sandboxTempDir === "string") {
      rmSync(token.sandboxTempDir, { force: true, recursive: true });
    }
  }
}

function createSandboxTempDir(hostEnv: BaselineHostEnv): string {
  return mkdtempSync(path.join(resolveSandboxTempDir(hostEnv), "openclaw-mxc-sandbox-"));
}

function assertWorkdirInsideWorkspace(workspaceDir: string, workdir: string): string {
  const workspace = realpathForExistingPath(workspaceDir, "sandbox workspace");
  const candidate = realpathForPotentialPath(workdir);
  if (isPathInside(workspace, candidate)) {
    return candidate;
  }
  throw new Error(
    `MXC sandbox workdir ${workdir} is outside the sandbox workspace ${workspaceDir}. ` +
      `Use a workdir inside the sandbox workspace.`,
  );
}

function resolveWorkdirInsideWorkspace(workspaceDir: string, workdir: string): string {
  const candidate = assertWorkdirInsideWorkspace(workspaceDir, workdir);
  try {
    if (statSync(candidate).isDirectory()) {
      return candidate;
    }
  } catch (err) {
    if (isMissingPathError(err)) {
      throw new Error(`MXC sandbox workdir ${workdir} does not exist.`, { cause: err });
    }
    throw err;
  }
  throw new Error(`MXC sandbox workdir ${workdir} is not a directory.`);
}

function realpathForExistingPath(value: string, label: string): string {
  try {
    return realpathSync(path.resolve(value));
  } catch (err) {
    if (isMissingPathError(err)) {
      throw new Error(`MXC ${label} ${value} does not exist.`, { cause: err });
    }
    throw err;
  }
}

function realpathForPotentialPath(value: string): string {
  const resolved = path.resolve(value);
  try {
    return realpathSync(resolved);
  } catch (err) {
    if (!isMissingPathError(err)) {
      throw err;
    }
    const parent = path.dirname(resolved);
    if (parent === resolved) {
      throw new Error(`MXC sandbox workdir ${value} does not exist.`, { cause: err });
    }
    return path.join(realpathForPotentialPath(parent), path.basename(resolved));
  }
}

function isNodeError(err: unknown): err is NodeJS.ErrnoException {
  return err instanceof Error && "code" in err;
}

// ENOTDIR means a parent component is a file, so the path can never resolve to a
// directory. Classifying it alongside ENOENT keeps validateWorkdir's "return null
// for unusable workdirs" contract intact instead of leaking a raw filesystem error.
function isMissingPathError(err: unknown): boolean {
  return isNodeError(err) && (err.code === "ENOENT" || err.code === "ENOTDIR");
}

function buildMxcLauncherOptions(config: MxcConfig, usePty: boolean): MxcLauncherOptions {
  const options: MxcLauncherOptions = {
    debug: config.debug ?? false,
    executablePath: resolveMxcBinaryPath(config.mxcBinaryPath),
  };
  if (!usePty) {
    options.usePty = false;
  }
  return options;
}

function createMxcLauncherPayload(
  config: MxcConfig,
  payload: ContainerConfig,
  usePty: boolean,
  sandboxTempDir: string,
): MxcExecFinalizeToken & { payloadFile: string } {
  const token = createLauncherPayloadFile(
    JSON.stringify({
      config: payload,
      options: buildMxcLauncherOptions(config, usePty),
    }),
  );
  token.sandboxTempDir = sandboxTempDir;
  return token;
}

function buildMxcLauncherArgv(payloadFile: string): [string, string, string, string] {
  return [process.execPath, resolveMxcLauncherPath(), "--payload-file", payloadFile];
}

/**
 * Creates a SandboxBackendHandle for a specific session.
 */
export function createMxcSandboxBackendHandle(params: {
  config: MxcConfig;
  runtimeId: string;
  workdir: string;
  agentWorkspaceDir?: string;
  skillsWorkspaceDir?: string;
  workspaceAccess?: MxcWorkspaceAccess;
}): SandboxBackendHandle {
  const baseline = loadSandboxBaselinePolicy({ policyPaths: params.config.mxcPolicyPaths });

  return {
    id: "mxc",
    runtimeId: params.runtimeId,
    runtimeLabel: params.runtimeId,
    workdir: params.workdir,
    workdirValidation: "backend",
    async validateWorkdir(workdir) {
      try {
        return resolveWorkdirInsideWorkspace(params.workdir, workdir);
      } catch (err) {
        if (err instanceof Error && err.message.startsWith("MXC sandbox workdir")) {
          return null;
        }
        throw err;
      }
    },
    capabilities: {},

    async buildExecSpec({ command, workdir, env, usePty }): Promise<SandboxBackendExecSpec> {
      const effectiveWorkdir = resolveWorkdirInsideWorkspace(
        params.workdir,
        workdir ?? params.workdir,
      );
      const workspaceAccess = params.workspaceAccess ?? "rw";
      const workspace = resolveMxcWorkspaceContext({ ...params, workspaceAccess });
      const runtimeWorkdir = resolveMxcRuntimeWorkdir(workspace, effectiveWorkdir);
      const baselineContext = resolveCurrentBaselineContext(workspace.activeWorkspaceDir);
      const sandboxTempDir = createSandboxTempDir(baselineContext.hostEnv);
      try {
        const payload = buildMxcContainerConfig({
          config: params.config,
          baseline,
          baselineContext,
          runtimeId: params.runtimeId,
          containerId: uniqueContainerId(params.runtimeId),
          command,
          sandboxTempDir,
          workdir: runtimeWorkdir,
          workspace,
          env,
        });

        // Spawn via a plugin-side Node launcher that calls
        // `@microsoft/mxc-sdk`'s `spawnSandboxFromConfig` directly. The SDK
        // owns the PTY allocation, so the launcher process appears as a plain
        // child to the host runtime. AppContainer on Windows needs ConPTY for
        // stdio inheritance; routing through the launcher keeps that detail
        // inside the plugin instead of forcing the host to promote argv into
        // a shell-quoted PTY command line.
        const payloadFile = createMxcLauncherPayload(
          params.config,
          payload,
          usePty,
          sandboxTempDir,
        );

        return {
          argv: buildMxcLauncherArgv(payloadFile.payloadFile),
          env: buildLauncherEnv(),
          stdinMode: usePty ? "pipe-open" : "pipe-closed",
          finalizeToken: payloadFile satisfies MxcExecFinalizeToken,
        };
      } catch (err) {
        rmSync(sandboxTempDir, { force: true, recursive: true });
        throw err;
      }
    },

    async finalizeExec({ token }) {
      cleanupLauncherPayloadFile(token);
    },

    createFsBridge: ({ sandbox }) => createMxcFsBridge({ sandbox }),

    async runShellCommand(
      cmdParams: SandboxBackendCommandParams,
    ): Promise<SandboxBackendCommandResult> {
      // Shell commands use a restrictive policy (no network, 30s timeout)
      const restrictiveConfig: MxcConfig = {
        ...params.config,
        network: "none",
        timeoutSeconds: 30,
        timeoutSecondsConfigured: true,
      };
      const effectiveWorkdir = path.resolve(params.workdir);
      const workspaceAccess = params.workspaceAccess ?? "rw";
      const workspace = resolveMxcWorkspaceContext({ ...params, workspaceAccess });
      const runtimeWorkdir = resolveMxcRuntimeWorkdir(workspace, effectiveWorkdir);
      const baselineContext = resolveCurrentBaselineContext(workspace.activeWorkspaceDir);
      const sandboxTempDir = createSandboxTempDir(baselineContext.hostEnv);
      const commandBridge = createWindowsCommandBridge({
        args: cmdParams.args,
        script: cmdParams.script,
        tempDir: sandboxTempDir,
      });
      const execInput = cmdParams.stdin === undefined ? Buffer.alloc(0) : toBuffer(cmdParams.stdin);

      try {
        const payload = buildMxcContainerConfig({
          config: restrictiveConfig,
          baseline,
          baselineContext,
          runtimeId: params.runtimeId,
          containerId: uniqueContainerId(params.runtimeId),
          command: commandBridge.command,
          args: cmdParams.args,
          sandboxTempDir,
          workdir: runtimeWorkdir,
          workspace,
          env: {},
        });

        const payloadFile = createMxcLauncherPayload(
          restrictiveConfig,
          payload,
          false,
          sandboxTempDir,
        );
        const argv = buildMxcLauncherArgv(payloadFile.payloadFile);
        try {
          const result = await runCommandBuffered(argv, {
            baseEnv: buildLauncherEnv(),
            input: execInput,
            maxOutputBytes: { stdout: 10 * 1024 * 1024, stderr: 10 * 1024 * 1024 },
            signal: cmdParams.signal,
            timeoutMs: 30_000,
          });
          if (cmdParams.signal?.aborted) {
            throw cmdParams.signal.reason instanceof Error
              ? cmdParams.signal.reason
              : (result.error ?? new Error("MXC command aborted"));
          }
          const { stdout, stderr } = result;
          const code = result.termination === "exit" ? (result.code ?? 1) : 1;
          if ((result.termination !== "exit" || code !== 0) && !cmdParams.allowFailure) {
            const commandError =
              result.error ??
              new Error(
                result.termination === "exit"
                  ? `MXC command exited with code ${code}`
                  : `MXC command terminated: ${result.termination}`,
              );
            throw Object.assign(commandError, {
              stdout,
              stderr,
              status: code,
            });
          }
          return { stdout, stderr, code };
        } finally {
          cleanupLauncherPayloadFile(payloadFile);
        }
      } finally {
        commandBridge.cleanup();
        rmSync(sandboxTempDir, { force: true, recursive: true });
      }
    },
  };
}

function toBuffer(value: Buffer | string): Buffer {
  if (Buffer.isBuffer(value)) {
    return value;
  }
  return Buffer.from(value, "utf-8");
}

/** Manager for `openclaw sandbox list` and `openclaw sandbox remove`. */
export const mxcSandboxBackendManager: SandboxBackendManager = {
  async describeRuntime() {
    return {
      running: false,
      actualConfigLabel: "mxc-process",
      configLabelMatch: true,
    };
  },
  async removeRuntime() {
    // MXC containers are ephemeral and destroyed on exit automatically.
  },
};

import { createHash } from "node:crypto";
import { statSync } from "node:fs";
import path from "node:path";
import type { ContainerConfig } from "@microsoft/mxc-sdk";
import { isPathInside } from "openclaw/plugin-sdk/file-access-runtime";
import type { MxcConfig } from "./config.js";
import { resolveBaselineReadonlyPaths, type BaselineHostEnv } from "./sandbox-baseline.js";
import type {
  LoadedSandboxBaselinePolicy,
  SandboxConfiguredPathEntry,
} from "./sandbox-policy-loader.js";
import { buildCommandLine } from "./windows-command.js";
import { normalizeWindowsProcessEnvRecord } from "./windows-env.js";
import {
  resolveMxcReadOnlySkillMounts,
  type MxcReadOnlySkillMount,
  type MxcWorkspaceAccess,
} from "./workspace-skill-mounts.js";

const MXC_SCHEMA_VERSION = "0.7.0-alpha";
const PROCESS_CONTAINER_NAME_MAX_LEN = 64;

type MxcFilesystemConfig = NonNullable<ContainerConfig["filesystem"]>;

type FilesystemPathSpec = {
  path: string;
  required: boolean;
  sources?: readonly string[];
};

type BaselineApplicationContext = {
  projectDir: string;
  hostEnv: BaselineHostEnv;
};

type MxcWorkspaceContext = {
  workspaceDir: string;
  agentWorkspaceDir: string;
  activeWorkspaceDir: string;
  skillsWorkspaceDir?: string;
  workdir: string;
  workspaceAccess: MxcWorkspaceAccess;
};

export function resolveCurrentBaselineContext(projectDir: string): BaselineApplicationContext {
  return {
    projectDir: path.resolve(projectDir),
    hostEnv: {
      SystemRoot: process.env.SystemRoot,
      WINDIR: process.env.WINDIR,
      ProgramFiles: process.env.ProgramFiles,
      ProgramW6432: process.env.ProgramW6432,
      "ProgramFiles(x86)": process.env["ProgramFiles(x86)"],
      TEMP: process.env.TEMP,
      TMP: process.env.TMP,
    },
  };
}

export function resolveMxcWorkspaceContext(params: {
  workdir: string;
  agentWorkspaceDir?: string;
  skillsWorkspaceDir?: string;
  workspaceAccess?: MxcWorkspaceAccess;
}): MxcWorkspaceContext {
  const workspaceAccess = params.workspaceAccess ?? "rw";
  const workspaceDir = path.resolve(params.workdir);
  const agentWorkspaceDir = path.resolve(params.agentWorkspaceDir ?? params.workdir);
  return {
    workspaceDir,
    agentWorkspaceDir,
    activeWorkspaceDir: workspaceAccess === "rw" ? agentWorkspaceDir : workspaceDir,
    ...(params.skillsWorkspaceDir
      ? { skillsWorkspaceDir: path.resolve(params.skillsWorkspaceDir) }
      : {}),
    workdir: workspaceDir,
    workspaceAccess,
  };
}

export function resolveMxcRuntimeWorkdir(
  workspace: MxcWorkspaceContext,
  requestedWorkdir: string,
): string {
  if (workspace.workspaceAccess !== "rw") {
    return path.resolve(requestedWorkdir);
  }

  const relativePath = path.relative(workspace.workspaceDir, requestedWorkdir);
  return relativePath === ""
    ? workspace.activeWorkspaceDir
    : path.join(workspace.activeWorkspaceDir, relativePath);
}

export function buildMxcContainerConfig(params: {
  config: MxcConfig;
  baseline: LoadedSandboxBaselinePolicy;
  baselineContext: BaselineApplicationContext;
  runtimeId: string;
  containerId: string;
  command: string;
  args?: readonly string[];
  sandboxTempDir: string;
  workdir: string;
  workspace: MxcWorkspaceContext;
  env: Record<string, string>;
}): ContainerConfig {
  const networkAllowed = params.config.network === "default";
  const filesystem = buildFilesystemConfig({
    baseline: params.baseline,
    context: params.baselineContext,
    sandboxTempDir: params.sandboxTempDir,
    workspace: params.workspace,
  });

  const processEnv = normalizeWindowsProcessEnvRecord({
    ...params.env,
    TEMP: params.sandboxTempDir,
    TMP: params.sandboxTempDir,
  });

  return {
    version: MXC_SCHEMA_VERSION,
    containerId: params.containerId,
    containment: params.config.containment,
    lifecycle: { destroyOnExit: true },
    process: {
      commandLine: buildCommandLine(params.command, params.args ?? []),
      cwd: resolveProcessCwd(params.workdir),
      env: processEnv,
      timeout: resolveProcessTimeoutSeconds(params.config, params.baseline) * 1000,
    },
    filesystem,
    ui: {
      disable: true,
      clipboard: "none",
      injection: false,
    },
    network: {
      defaultPolicy: networkAllowed ? "allow" : "block",
      enforcementMode: "capabilities",
    },
    processContainer: {
      name: processContainerName(params.runtimeId),
      leastPrivilege: true,
      capabilities: networkAllowed ? ["internetClient"] : [],
      ui: {
        isolation: "container",
        desktopSystemControl: false,
        systemSettings: "none",
        ime: false,
      },
    },
  };
}

function buildFilesystemConfig(params: {
  baseline: LoadedSandboxBaselinePolicy;
  context: BaselineApplicationContext;
  sandboxTempDir: string;
  workspace: MxcWorkspaceContext;
}): MxcFilesystemConfig {
  const readwritePathSpecs = resolveWorkspaceReadwritePathSpecs(params.workspace);
  const readonlyPathSpecs = [
    ...resolveWorkspaceReadonlyPathSpecs(params.workspace),
    ...resolveBaselineReadonlyPathSpecs(params.baseline, params.context),
    ...resolveProtectedSkillPolicyPathSpecs(params.workspace),
  ];

  if (params.baseline.filesystem.restrictToProjectDir) {
    const projectDirPath = params.context.projectDir;
    if (params.workspace.workspaceAccess === "rw") {
      readwritePathSpecs.push(requiredFilesystemPath(projectDirPath));
    } else {
      readonlyPathSpecs.push(requiredFilesystemPath(projectDirPath));
    }
    readwritePathSpecs.push(requiredFilesystemPath(path.resolve(params.sandboxTempDir)));
    readwritePathSpecs.push(
      ...params.baseline.configuredPaths.readwritePaths.map(createConfiguredFilesystemPath),
    );
  }

  const protectedSkillPolicyPaths = resolveMxcProtectedSkillPolicyPaths(params.workspace);
  // ProcessContainer writable-parent grants override nested read-only grants.
  // Fail closed instead of claiming protected skill overlays are enforceable.
  assertNoMxcReadwriteReadonlyOverlap({
    readwritePaths: resolveExistingFilesystemPaths(readwritePathSpecs, "readwrite"),
    readonlyPaths: protectedSkillPolicyPaths,
  });

  const readonlyPaths = resolveExistingFilesystemPaths(readonlyPathSpecs, "read-only");
  const readwritePaths = resolveExistingFilesystemPaths(readwritePathSpecs, "readwrite");
  assertNoMxcReadwriteReadonlyOverlap({ readwritePaths, readonlyPaths });

  return {
    readonlyPaths,
    deniedPaths: undefined,
    readwritePaths,
    clearPolicyOnExit: true,
  };
}

function resolveWorkspaceReadwritePathSpecs(workspace: MxcWorkspaceContext): FilesystemPathSpec[] {
  if (workspace.workspaceAccess !== "rw") {
    return [];
  }
  return [requiredFilesystemPath(workspace.activeWorkspaceDir)];
}

function resolveWorkspaceReadonlyPathSpecs(workspace: MxcWorkspaceContext): FilesystemPathSpec[] {
  if (workspace.workspaceAccess === "rw") {
    return [];
  }

  const readonlyPathSpecs = [requiredFilesystemPath(workspace.workspaceDir)];
  if (
    workspace.workspaceAccess === "ro" &&
    normalizePathForComparison(workspace.agentWorkspaceDir) !==
      normalizePathForComparison(workspace.workspaceDir)
  ) {
    readonlyPathSpecs.push(requiredFilesystemPath(workspace.agentWorkspaceDir));
  }
  return readonlyPathSpecs;
}

function resolveBaselineReadonlyPathSpecs(
  baseline: LoadedSandboxBaselinePolicy,
  context: BaselineApplicationContext,
): FilesystemPathSpec[] {
  return [
    ...resolveBaselineReadonlyPaths(context.hostEnv).map((candidatePath) =>
      optionalFilesystemPath(path.resolve(candidatePath)),
    ),
    ...baseline.configuredPaths.readonlyPaths.map(createConfiguredFilesystemPath),
  ];
}

function resolveMxcProtectedSkillPolicyPaths(context: MxcWorkspaceContext): string[] {
  const deduped = new Map<string, string>();
  for (const mount of resolveMxcProtectedSkillMounts(context)) {
    const hostPath = path.resolve(mount.hostPath);
    deduped.set(normalizePathForComparison(hostPath), hostPath);
    const containerPath = path.resolve(mount.containerPath);
    deduped.set(normalizePathForComparison(containerPath), containerPath);
  }
  return [...deduped.values()];
}

function resolveProtectedSkillPolicyPathSpecs(context: MxcWorkspaceContext): FilesystemPathSpec[] {
  return resolveMxcProtectedSkillPolicyPaths(context).map((candidatePath) =>
    optionalFilesystemPath(candidatePath),
  );
}

function resolveMxcProtectedSkillMounts(
  context: MxcWorkspaceContext,
): readonly MxcReadOnlySkillMount[] {
  return resolveMxcReadOnlySkillMounts({
    agentWorkspaceDir: context.agentWorkspaceDir,
    skillsWorkspaceDir: context.skillsWorkspaceDir,
    workdir: context.workdir,
    workspaceAccess: context.workspaceAccess,
  });
}

function resolveExistingFilesystemPaths(
  pathSpecs: readonly FilesystemPathSpec[],
  accessLabel: "read-only" | "readwrite",
): string[] {
  const deduped = new Map<
    string,
    {
      path: string;
      required: boolean;
      sources: Set<string>;
    }
  >();

  for (const pathSpec of pathSpecs) {
    const key = normalizePathForComparison(pathSpec.path);
    const existing = deduped.get(key);
    if (existing) {
      existing.required ||= pathSpec.required;
      for (const source of pathSpec.sources ?? []) {
        existing.sources.add(source);
      }
      continue;
    }

    deduped.set(key, {
      path: pathSpec.path,
      required: pathSpec.required,
      sources: new Set(pathSpec.sources ?? []),
    });
  }

  const resolvedPaths: string[] = [];
  for (const pathSpec of deduped.values()) {
    if (hostPathExists(pathSpec.path)) {
      resolvedPaths.push(pathSpec.path);
      continue;
    }
    if (!pathSpec.required) {
      continue;
    }
    throw new Error(
      buildMissingFilesystemPathMessage(pathSpec.path, accessLabel, pathSpec.sources),
    );
  }
  return resolvedPaths;
}

function requiredFilesystemPath(pathValue: string): FilesystemPathSpec {
  return {
    path: path.resolve(pathValue),
    required: true,
  };
}

function optionalFilesystemPath(pathValue: string): FilesystemPathSpec {
  return {
    path: path.resolve(pathValue),
    required: false,
  };
}

function createConfiguredFilesystemPath(pathEntry: SandboxConfiguredPathEntry): FilesystemPathSpec {
  return {
    path: path.resolve(pathEntry.path),
    required: true,
    sources: pathEntry.sources,
  };
}

function buildMissingFilesystemPathMessage(
  pathValue: string,
  accessLabel: "read-only" | "readwrite",
  sources: ReadonlySet<string>,
): string {
  const sourceLabel = [...sources].join(", ");
  if (sourceLabel) {
    return (
      `MXC sandbox ${accessLabel} path ${pathValue} configured by ${sourceLabel} ` +
      `is missing on the host. Recreate the path or update the policy file before launching the sandbox.`
    );
  }
  return `MXC sandbox ${accessLabel} path ${pathValue} does not exist on the host.`;
}

function processContainerName(runtimeId: string): string {
  if (runtimeId.length <= PROCESS_CONTAINER_NAME_MAX_LEN) {
    return runtimeId;
  }
  const hash = createHash("sha256").update(runtimeId).digest("hex").slice(0, 8);
  return `${runtimeId.slice(0, PROCESS_CONTAINER_NAME_MAX_LEN - hash.length - 1)}-${hash}`;
}

function resolveProcessCwd(workdir: string): string {
  return workdir;
}

function resolveProcessTimeoutSeconds(
  config: MxcConfig,
  baseline: LoadedSandboxBaselinePolicy,
): number {
  if (config.timeoutSecondsConfigured === true) {
    return Math.min(config.timeoutSeconds, baseline.process.timeoutSeconds);
  }
  return baseline.process.timeoutSeconds;
}

function assertNoMxcReadwriteReadonlyOverlap(params: {
  readwritePaths: readonly string[];
  readonlyPaths: readonly string[];
}): void {
  for (const readwritePath of params.readwritePaths) {
    for (const readonlyPath of params.readonlyPaths) {
      if (pathsOverlap(readwritePath, readonlyPath)) {
        throw new Error(
          `MXC readwrite path ${readwritePath} overlaps read-only path ${readonlyPath}. Windows MXC cannot safely enforce nested read-only overlays under writable paths.`,
        );
      }
    }
  }
}

function pathsOverlap(first: string, second: string): boolean {
  const left = normalizePathForComparison(first);
  const right = normalizePathForComparison(second);
  return isPathInside(left, right) || isPathInside(right, left);
}

function normalizePathForComparison(value: string): string {
  const resolved = path.resolve(value);
  return process.platform === "win32" ? resolved.toLowerCase() : resolved;
}

function hostPathExists(candidatePath: string): boolean {
  try {
    statSync(candidatePath);
    return true;
  } catch (err) {
    if (isNodeError(err)) {
      return false;
    }
    throw err;
  }
}

function isNodeError(err: unknown): err is NodeJS.ErrnoException {
  return err instanceof Error && "code" in err;
}

#!/usr/bin/env node

import { readFileSync, rmSync } from "node:fs";
import path from "node:path";
import { pathToFileURL } from "node:url";

export function decodePayload(argv) {
  const payloadFileIndex = argv.indexOf("--payload-file");
  if (payloadFileIndex < 0) {
    throw new Error("Missing --payload-file");
  }
  const payloadFile = argv[payloadFileIndex + 1];
  if (!payloadFile) {
    throw new Error("Missing --payload-file value");
  }
  const payloadJson = readFileSync(payloadFile, "utf8");
  rmSync(path.dirname(payloadFile), { force: true, recursive: true });
  return JSON.parse(payloadJson);
}

const FORWARDED_SIGNAL_EXIT_GRACE_MS = 1000;
const FORWARDED_SIGNALS = ["SIGTERM", "SIGINT", "SIGHUP"];

function formatErrorStack(error) {
  if (error && typeof error === "object" && typeof error.stack === "string") {
    return error.stack;
  }
  return String(error);
}

export function forwardSignals(spawned, options = {}) {
  let exitTimer;
  const exitGraceMs = options.exitGraceMs ?? FORWARDED_SIGNAL_EXIT_GRACE_MS;
  const scheduleExit = (signal) => {
    if (exitTimer) {
      return;
    }
    const setTimeoutFn = options.setTimeout?.bind(undefined) ?? setTimeout;
    exitTimer = setTimeoutFn(() => {
      const exit = options.exit?.bind(undefined) ?? ((code) => process.exit(code));
      exit(signalExitCode(signal));
    }, exitGraceMs);
    exitTimer?.unref?.();
  };

  for (const signal of FORWARDED_SIGNALS) {
    process.on(signal, () => {
      try {
        spawned.kill(signal);
      } catch {
        // Ignore kill errors while the sandbox process is already exiting.
      }
      scheduleExit(signal);
    });
  }
}

function bridgeStdio(pty) {
  pty.onData((data) => {
    process.stdout.write(data);
  });

  process.stdin.setEncoding("utf8");
  process.stdin.on("data", (data) => {
    pty.write(data);
  });
  process.stdin.on("end", () => {
    pty.write("\x04");
  });
}

function bridgeChildProcess(child) {
  child.stdout?.on("data", (data) => {
    process.stdout.write(data);
  });
  child.stderr?.on("data", (data) => {
    process.stderr.write(data);
  });
  process.stdin.on("data", (data) => {
    child.stdin?.write(data);
  });
  process.stdin.on("end", () => {
    child.stdin?.end();
  });
}

export function exitOnChildProcessClose(child, options = {}) {
  child.on("close", (exitCode, signal) => {
    const exit = options.exit?.bind(undefined) ?? ((code) => process.exit(code));
    exit(typeof exitCode === "number" ? exitCode : signalExitCode(signal));
  });
}

function attachPtyProcess(spawned) {
  bridgeStdio(spawned);
  forwardSignals(spawned);
  spawned.onExit(({ exitCode, signal }) => {
    process.exit(typeof exitCode === "number" ? exitCode : signalExitCode(signal));
  });
}

function attachChildProcess(spawned) {
  bridgeChildProcess(spawned);
  forwardSignals(spawned);
  exitOnChildProcessClose(spawned);
}

export async function launchSandbox(spawnSandboxFromConfig, config, options, bridges = {}) {
  // Normalize sync and Promise-returning SDK implementations before selecting an I/O bridge.
  const spawned = await spawnSandboxFromConfig(config, options ?? {});

  if (typeof spawned.onData === "function") {
    (bridges.pty ?? attachPtyProcess)(spawned);
    return;
  }

  (bridges.child ?? attachChildProcess)(spawned);
}

const SIGNAL_NUMBERS = new Map([
  ["SIGHUP", 1],
  ["SIGINT", 2],
  ["SIGQUIT", 3],
  ["SIGTERM", 15],
]);

export function signalExitCode(signal) {
  if (typeof signal === "number" && Number.isFinite(signal)) {
    return 128 + signal;
  }
  if (typeof signal === "string") {
    const signalNumber = SIGNAL_NUMBERS.get(signal);
    if (signalNumber !== undefined) {
      return 128 + signalNumber;
    }
  }
  return 1;
}

function isMain() {
  const mainPath = process.argv[1];
  if (!mainPath) {
    return false;
  }
  return import.meta.url === pathToFileURL(path.resolve(mainPath)).href;
}

export async function main() {
  try {
    const { config, options } = decodePayload(process.argv.slice(2));
    const { spawnSandboxFromConfig } = await import("@microsoft/mxc-sdk");
    await launchSandbox(spawnSandboxFromConfig, config, options);
  } catch (error) {
    process.stderr.write(`${formatErrorStack(error)}\n`);
    process.exit(127);
  }
}

if (isMain()) {
  void main();
}

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

function isMxcPluginRoot(dir: string): boolean {
  return (
    fs.existsSync(path.join(dir, "openclaw.plugin.json")) &&
    fs.existsSync(path.join(dir, "package.json"))
  );
}

function resolveMxcPluginRoot(moduleUrl: string = import.meta.url): string {
  let cursor = path.dirname(fileURLToPath(moduleUrl));
  for (let i = 0; i < 6; i += 1) {
    if (isMxcPluginRoot(cursor)) {
      return cursor;
    }
    const parent = path.dirname(cursor);
    if (parent === cursor) {
      break;
    }
    cursor = parent;
  }
  throw new Error(`[mxc] cannot locate plugin root from ${moduleUrl}`);
}

export function resolveMxcLauncherPath(moduleUrl: string = import.meta.url): string {
  const root = resolveMxcPluginRoot(moduleUrl);
  const sourceLauncher = path.join(root, "src", "mxc-spawn-launcher.mjs");
  const rootDistLauncher = path.join(root, "mxc-spawn-launcher.mjs");
  const packageDistLauncher = path.join(root, "dist", "mxc-spawn-launcher.mjs");
  if (fs.existsSync(sourceLauncher)) {
    return sourceLauncher;
  }
  if (fs.existsSync(rootDistLauncher)) {
    return rootDistLauncher;
  }
  if (fs.existsSync(packageDistLauncher)) {
    return packageDistLauncher;
  }
  throw new Error(
    `[mxc] launcher not found; searched ${sourceLauncher}, ${rootDistLauncher}, and ${packageDistLauncher}`,
  );
}

import type { OpenClawPluginApi } from "openclaw/plugin-sdk/plugin-entry";
import { registerSandboxBackend } from "openclaw/plugin-sdk/sandbox";
import { resolveMxcBinaryPath } from "./binary-resolver.js";
import { resolveConfig } from "./config.js";
import { createMxcSandboxBackendFactory } from "./mxc-backend-factory.js";
import { mxcSandboxBackendManager } from "./mxc-backend.js";
import { assertMxcReadiness, warnMxcHostPrepIfNeeded } from "./readiness.js";

export function registerMxcPlugin(api: OpenClawPluginApi): void {
  if (api.registrationMode !== "full") {
    return;
  }

  const config = resolveConfig(api.pluginConfig);

  if (process.platform !== "win32") {
    console.warn(
      `[mxc] Sandbox backend is Windows-only and not available on ${process.platform}. Plugin will be dormant.`,
    );
    return;
  }

  // IsoEnvBroker availability is the ProcessContainer readiness signal for this plugin.
  // Binary and host readiness checks fail load with actionable remediation.
  try {
    resolveMxcBinaryPath(config.mxcBinaryPath);
  } catch (err) {
    const reason = err instanceof Error ? err.message : String(err);
    throw new Error(
      `[mxc] MXC sandbox backend cannot load: ${reason}. Install @microsoft/mxc-sdk or set mxcBinaryPath.`,
      { cause: err },
    );
  }
  assertMxcReadiness();

  // Advisory: warn (don't block) when the system drive lacks AppContainer
  // directory-access ACEs, which only degrades in-sandbox directory listing.
  warnMxcHostPrepIfNeeded();

  // Register the backend
  const unregister = registerSandboxBackend("mxc", {
    factory: createMxcSandboxBackendFactory(config),
    manager: mxcSandboxBackendManager,
  });

  // Eager CLI registrations must retire even if Gateway services never start.
  api.lifecycle.registerRuntimeLifecycle({
    id: "mxc-sandbox-cleanup",
    cleanup: ({ reason, sessionKey, runId }) => {
      if (sessionKey !== undefined || runId !== undefined) {
        return;
      }
      if (reason === "disable" || reason === "restart") {
        unregister();
      }
    },
  });
}

import { execFileSync } from "node:child_process";
import path from "node:path";

type ReadinessDeps = {
  execFileSync: typeof execFileSync;
};

const DEFAULT_DEPS: ReadinessDeps = { execFileSync };

function resolveWindowsSystemExecutable(name: string): string {
  const systemRoot = process.env.SystemRoot || process.env.WINDIR;
  return path.win32.join(systemRoot || "C:\\Windows", "System32", name);
}

// The IsoEnvBroker service is demand-started, so it does not need to be RUNNING
// at plugin load: we only require that it is installed. `sc.exe query` exits
// non-zero (1060) when the service is absent, which surfaces as a thrown error;
// a successful query means the service exists and Windows will start it on use.
function assertWindowsIsoEnvBrokerInstalled(deps: ReadinessDeps): void {
  try {
    deps.execFileSync(resolveWindowsSystemExecutable("sc.exe"), ["query", "IsoEnvBroker"], {
      encoding: "utf-8",
      stdio: "pipe",
      timeout: 5_000,
      windowsHide: true,
    });
  } catch (error) {
    const detail = error instanceof Error && error.message ? `: ${error.message.trim()}` : "";
    throw new Error(
      `[mxc] MXC Windows ProcessContainer sandbox is not ready: IsoEnvBroker service is not installed${detail}. ` +
        `Install the IsoEnvBroker service before enabling MXC sandbox execution.`,
      { cause: error },
    );
  }
}

// AppContainer processes need directory-traversal/list rights on the system
// drive root (C:\) to enumerate directories inside the sandbox.
// `wxc-host-prep prepare-system-drive` adds ACEs for the well-known
// ALL APPLICATION PACKAGES (S-1-15-2-1) and ALL RESTRICTED APPLICATION PACKAGES
// (S-1-15-2-2) SIDs. Without this, directory listing (e.g. `dir`) inside the
// sandbox fails with "Access is denied". This is advisory: the sandbox still
// runs basic cmd.exe read/write workloads without it, so a missing grant warns
// rather than blocking activation.
function isSystemDrivePrepared(deps: ReadinessDeps): boolean {
  const systemDrive = process.env.SystemDrive || "C:";
  let output: string;
  try {
    output = deps.execFileSync(resolveWindowsSystemExecutable("icacls.exe"), [`${systemDrive}\\`], {
      encoding: "utf-8",
      stdio: "pipe",
      timeout: 5_000,
      windowsHide: true,
    });
  } catch {
    // If icacls itself fails, assume prepared rather than emitting a spurious
    // warning on a host we cannot probe.
    return true;
  }
  // Look for the well-known ALL APPLICATION PACKAGES SID (S-1-15-2-1) or its
  // display name. Both forms can appear depending on OS locale/version.
  return output.includes("S-1-15-2-1") || output.includes("APPLICATION PACKAGES");
}

function systemDrivePrepWarning(systemDrive: string): string {
  return (
    `[mxc] MXC sandbox host preparation incomplete: the system drive root (${systemDrive}\\) ` +
    `does not grant directory access to AppContainer processes, so directory listing ` +
    `(e.g. \`dir\`) inside the sandbox will fail with "Access is denied". Basic read/write ` +
    `workloads still run.\n` +
    `Fix (one-time, elevated): wxc-host-prep prepare-system-drive (ships with @microsoft/mxc-sdk).`
  );
}

/**
 * Emits an advisory warning when the system drive is not prepared for
 * AppContainer directory access. Non-fatal: the sandbox still activates.
 */
export function warnMxcHostPrepIfNeeded(
  params: {
    platform?: NodeJS.Platform;
    deps?: Partial<ReadinessDeps>;
    warn?: (message: string) => void;
  } = {},
): void {
  const platform = params.platform ?? process.platform;
  if (platform !== "win32") {
    return;
  }
  const deps = { ...DEFAULT_DEPS, ...params.deps };
  if (!isSystemDrivePrepared(deps)) {
    const warn = params.warn ?? ((message: string) => console.warn(message));
    warn(systemDrivePrepWarning(process.env.SystemDrive || "C:"));
  }
}

export function assertMxcReadiness(
  params: {
    platform?: NodeJS.Platform;
    deps?: Partial<ReadinessDeps>;
  } = {},
): void {
  const platform = params.platform ?? process.platform;
  if (platform !== "win32") {
    return;
  }
  const deps = { ...DEFAULT_DEPS, ...params.deps };
  assertWindowsIsoEnvBrokerInstalled(deps);
}

/**
 * Deterministic MXC sandbox baseline policy helpers.
 *
 * These helpers only include policy surfaces the Windows ProcessContainer path
 * currently enforces: workspace/read-only/read-write paths and process timeout.
 */

import { win32 } from "node:path";

const BASELINE_TIMEOUT_SECONDS = 300;

type BaselineFilesystemPolicy = {
  restrictToProjectDir: boolean;
  additionalReadonlyPaths: readonly string[];
  additionalReadwritePaths: readonly string[];
};

export type BaselineFilesystemPolicyInput = {
  restrictToProjectDir?: boolean;
  additionalReadonlyPaths?: readonly string[];
  additionalReadwritePaths?: readonly string[];
};

export type SandboxBaselinePolicy = {
  filesystem: BaselineFilesystemPolicy;
  process: {
    timeoutSeconds: number;
    timeoutSecondsConfigured: boolean;
  };
};

export type SandboxBaselinePolicyInput = {
  filesystem?: BaselineFilesystemPolicyInput;
  process?: {
    timeoutSeconds?: number;
  };
};

type BaselineTempEnv = {
  TEMP?: string;
  TMP?: string;
};

type BaselineReadonlyEnv = {
  SystemRoot?: string;
  WINDIR?: string;
  ProgramFiles?: string;
  ProgramW6432?: string;
  "ProgramFiles(x86)"?: string;
};

export type BaselineHostEnv = BaselineTempEnv & BaselineReadonlyEnv;

export const DEFAULT_SANDBOX_BASELINE: SandboxBaselinePolicy = {
  filesystem: {
    restrictToProjectDir: true,
    additionalReadonlyPaths: [],
    additionalReadwritePaths: [],
  },
  process: {
    timeoutSeconds: BASELINE_TIMEOUT_SECONDS,
    timeoutSecondsConfigured: false,
  },
};

function firstNonBlankEnv(...values: Array<string | undefined>): string | undefined {
  return values.find((value) => value?.trim());
}

export function resolveSandboxBaseline(
  input: SandboxBaselinePolicyInput = {},
): SandboxBaselinePolicy {
  const timeoutSecondsConfigured = input.process?.timeoutSeconds !== undefined;
  const timeoutSeconds = input.process?.timeoutSeconds ?? BASELINE_TIMEOUT_SECONDS;
  if (!Number.isFinite(timeoutSeconds) || timeoutSeconds < 1) {
    throw new RangeError("Sandbox baseline timeoutSeconds must be at least 1.");
  }

  return {
    filesystem: {
      restrictToProjectDir: input.filesystem?.restrictToProjectDir ?? true,
      additionalReadonlyPaths: [...(input.filesystem?.additionalReadonlyPaths ?? [])],
      additionalReadwritePaths: [...(input.filesystem?.additionalReadwritePaths ?? [])],
    },
    process: {
      timeoutSeconds,
      timeoutSecondsConfigured,
    },
  };
}

export function resolveSandboxTempDir(env: BaselineTempEnv = {}): string {
  return firstNonBlankEnv(env.TEMP, env.TMP) ?? "C:\\Windows\\Temp";
}

export function resolveBaselineReadonlyPaths(env: BaselineReadonlyEnv): string[] {
  const systemRoot = firstNonBlankEnv(env.SystemRoot, env.WINDIR) ?? "C:\\Windows";
  const programFiles = firstNonBlankEnv(env.ProgramFiles, env.ProgramW6432) ?? "C:\\Program Files";
  const programFilesX86 = firstNonBlankEnv(env["ProgramFiles(x86)"]) ?? "C:\\Program Files (x86)";
  return dedupeStable([
    programFiles,
    programFilesX86,
    win32.join(systemRoot, "System32"),
    win32.join(systemRoot, "SysWOW64"),
  ]);
}

function dedupeStable(values: readonly string[]): string[] {
  const deduped: string[] = [];
  const seen = new Set<string>();
  for (const value of values) {
    if (seen.has(value)) {
      continue;
    }
    seen.add(value);
    deduped.push(value);
  }
  return deduped;
}

import { readFileSync, statSync } from "node:fs";
import { win32 } from "node:path";
import { formatErrorMessage } from "openclaw/plugin-sdk/error-runtime";
import { z } from "zod";
import {
  DEFAULT_SANDBOX_BASELINE,
  resolveSandboxBaseline,
  type BaselineFilesystemPolicyInput,
  type SandboxBaselinePolicy,
  type SandboxBaselinePolicyInput,
} from "./sandbox-baseline.js";

type SandboxPolicyLoaderOptions = {
  policyPaths?: readonly string[];
};

type SandboxPolicyPathField =
  | "filesystem.additionalReadonlyPaths"
  | "filesystem.additionalReadwritePaths";

export type SandboxConfiguredPathEntry = {
  path: string;
  sources: readonly string[];
};

type SandboxConfiguredPaths = {
  readonlyPaths: readonly SandboxConfiguredPathEntry[];
  readwritePaths: readonly SandboxConfiguredPathEntry[];
};

type SandboxPolicyLayer = SandboxBaselinePolicyInput & {
  configuredPaths: SandboxConfiguredPaths;
};

export type LoadedSandboxBaselinePolicy = SandboxBaselinePolicy & {
  configuredPaths: SandboxConfiguredPaths;
};

type SandboxPolicySource = {
  label: string;
  policy: SandboxPolicyLayer;
};

type MutableConfiguredPathMaps = {
  readonlyPaths: Map<string, SandboxConfiguredPathEntry>;
  readwritePaths: Map<string, SandboxConfiguredPathEntry>;
};

const stringArraySchema = z.array(z.string());
const hardeningBooleanSchema = z.literal(true);
const filesystemPolicySchema = z
  .object({
    restrictToProjectDir: hardeningBooleanSchema.optional(),
    additionalReadonlyPaths: stringArraySchema.optional(),
    additionalReadwritePaths: stringArraySchema.optional(),
  })
  .strict();
const processPolicySchema = z
  .object({
    timeoutSeconds: z.number().finite().min(1).optional(),
  })
  .strict();

const SandboxPolicyLayerSchema = z
  .object({
    filesystem: filesystemPolicySchema.optional(),
    process: processPolicySchema.optional(),
  })
  .strict();

export function loadSandboxBaselinePolicy(
  options: SandboxPolicyLoaderOptions = {},
): LoadedSandboxBaselinePolicy {
  const sources: SandboxPolicySource[] = [];

  for (const policyPath of options.policyPaths ?? []) {
    sources.push({ label: policyPath, policy: readSandboxPolicyFile(policyPath) });
  }

  const merged = mergeSandboxPolicyLayers(sources);
  const resolved = resolveSandboxBaseline(merged);
  return {
    ...resolved,
    process: {
      ...resolved.process,
      timeoutSecondsConfigured: sources.some(
        ({ policy }) => policy.process?.timeoutSeconds !== undefined,
      ),
    },
    configuredPaths: merged.configuredPaths,
  };
}

function readSandboxPolicyFile(policyPath: string): SandboxPolicyLayer {
  let parsed: unknown;
  try {
    parsed = JSON.parse(readFileSync(policyPath, "utf-8"));
  } catch (err) {
    throw policyFileError(policyPath, err);
  }

  try {
    return parseSandboxPolicyLayer(parsed, policyPath);
  } catch (err) {
    throw policyFileError(policyPath, err);
  }
}

function parseSandboxPolicyLayer(value: unknown, sourceLabel: string): SandboxPolicyLayer {
  const parsed = SandboxPolicyLayerSchema.safeParse(value);
  if (!parsed.success) {
    throw new TypeError(formatSandboxPolicyIssue(sourceLabel, parsed.error.issues[0]));
  }

  const filesystem = parsed.data.filesystem;
  const readonlyPaths = normalizeConfiguredPaths(
    filesystem?.additionalReadonlyPaths,
    sourceLabel,
    "filesystem.additionalReadonlyPaths",
  );
  const readwritePaths = normalizeConfiguredPaths(
    filesystem?.additionalReadwritePaths,
    sourceLabel,
    "filesystem.additionalReadwritePaths",
  );

  return {
    ...parsed.data,
    filesystem: filesystem
      ? {
          ...filesystem,
          ...(readonlyPaths.length > 0
            ? {
                additionalReadonlyPaths: readonlyPaths.map((entry) => entry.path),
              }
            : {}),
          ...(readwritePaths.length > 0
            ? {
                additionalReadwritePaths: readwritePaths.map((entry) => entry.path),
              }
            : {}),
        }
      : undefined,
    configuredPaths: {
      readonlyPaths,
      readwritePaths,
    },
  };
}

function mergeSandboxPolicyLayers(sources: readonly SandboxPolicySource[]): SandboxPolicyLayer {
  const timeoutCandidates = [DEFAULT_SANDBOX_BASELINE.process.timeoutSeconds];
  const filesystem: BaselineFilesystemPolicyInput = {
    restrictToProjectDir: DEFAULT_SANDBOX_BASELINE.filesystem.restrictToProjectDir,
    additionalReadonlyPaths: [],
    additionalReadwritePaths: [],
  };
  const configuredPathMaps: MutableConfiguredPathMaps = {
    readonlyPaths: new Map<string, SandboxConfiguredPathEntry>(),
    readwritePaths: new Map<string, SandboxConfiguredPathEntry>(),
  };

  for (const { policy, label } of sources) {
    mergeFilesystemPolicy(filesystem, policy.filesystem);
    mergeConfiguredPathEntries(
      configuredPathMaps.readonlyPaths,
      policy.configuredPaths.readonlyPaths,
    );
    mergeConfiguredPathEntries(
      configuredPathMaps.readwritePaths,
      policy.configuredPaths.readwritePaths,
    );
    const timeoutSeconds = policy.process?.timeoutSeconds;
    if (timeoutSeconds !== undefined) {
      assertPositiveFiniteNumber(timeoutSeconds, `${label}.process.timeoutSeconds`);
      timeoutCandidates.push(timeoutSeconds);
    }
  }

  return {
    filesystem: {
      ...filesystem,
      additionalReadonlyPaths: [...configuredPathMaps.readonlyPaths.values()].map(
        (entry) => entry.path,
      ),
      additionalReadwritePaths: [...configuredPathMaps.readwritePaths.values()].map(
        (entry) => entry.path,
      ),
    },
    process: {
      timeoutSeconds: Math.min(...timeoutCandidates),
    },
    configuredPaths: {
      readonlyPaths: [...configuredPathMaps.readonlyPaths.values()],
      readwritePaths: [...configuredPathMaps.readwritePaths.values()],
    },
  };
}

function mergeFilesystemPolicy(
  target: BaselineFilesystemPolicyInput | undefined,
  layer: BaselineFilesystemPolicyInput | undefined,
): void {
  if (!target || !layer) {
    return;
  }

  target.restrictToProjectDir = mostRestrictiveBoolean(
    DEFAULT_SANDBOX_BASELINE.filesystem.restrictToProjectDir,
    target.restrictToProjectDir,
    layer.restrictToProjectDir,
  );
}

function mergeConfiguredPathEntries(
  target: Map<string, SandboxConfiguredPathEntry>,
  entries: readonly SandboxConfiguredPathEntry[],
): void {
  for (const entry of entries) {
    const existing = target.get(entry.path);
    if (!existing) {
      target.set(entry.path, entry);
      continue;
    }
    target.set(entry.path, {
      path: entry.path,
      sources: [...new Set([...existing.sources, ...entry.sources])],
    });
  }
}

function normalizeConfiguredPaths(
  values: readonly string[] | undefined,
  sourceLabel: string,
  field: SandboxPolicyPathField,
): SandboxConfiguredPathEntry[] {
  if (!values || values.length === 0) {
    return [];
  }

  const deduped = new Map<string, SandboxConfiguredPathEntry>();
  for (const [index, value] of values.entries()) {
    const source = `${sourceLabel}.${field}[${index}]`;
    const trimmed = value.trim();
    if (trimmed.length === 0) {
      throw new TypeError(`Sandbox policy field ${source} must not be blank.`);
    }
    if (!win32.isAbsolute(trimmed)) {
      throw new TypeError(`Sandbox policy field ${source} must be an absolute Windows path.`);
    }

    const normalized = win32.normalize(trimmed);
    assertConfiguredPathExists(normalized, source);

    const existing = deduped.get(normalized);
    if (!existing) {
      deduped.set(normalized, { path: normalized, sources: [source] });
      continue;
    }
    deduped.set(normalized, {
      path: normalized,
      sources: [...new Set([...existing.sources, source])],
    });
  }

  return [...deduped.values()];
}

function assertConfiguredPathExists(pathValue: string, source: string): void {
  try {
    statSync(pathValue);
  } catch (err) {
    if (isNodeError(err)) {
      if (err.code === "ENOENT") {
        throw new Error(
          `Sandbox policy path ${pathValue} configured by ${source} does not exist on the host. ` +
            `Create the path or update the policy file.`,
          { cause: err },
        );
      }
      throw new Error(
        `Sandbox policy path ${pathValue} configured by ${source} is not accessible on the host: ${formatErrorMessage(err)}`,
        { cause: err },
      );
    }
    throw err;
  }
}

function mostRestrictiveBoolean(
  defaultValue: boolean,
  ...values: readonly (boolean | undefined)[]
): boolean {
  return defaultValue || values.some((value) => value === true);
}

function assertPositiveFiniteNumber(value: unknown, label: string): asserts value is number {
  if (typeof value !== "number" || !Number.isFinite(value) || value < 1) {
    throw new TypeError(`Sandbox policy field ${label} must be a positive number.`);
  }
}

function policyFileError(policyPath: string, err: unknown): Error {
  if (isNodeError(err) && err.code === "ENOENT") {
    return new Error(
      `Configured sandbox policy file ${policyPath} does not exist. Remove it from mxcPolicyPaths or create the file.`,
      { cause: err },
    );
  }
  return new Error(
    `Failed to load sandbox policy file at ${policyPath}: ${formatErrorMessage(err)}`,
    {
      cause: err instanceof Error ? err : undefined,
    },
  );
}

function formatSandboxPolicyIssue(sourceLabel: string, issue: z.ZodIssue | undefined): string {
  if (!issue) {
    return `Sandbox policy at ${sourceLabel} is invalid.`;
  }
  if (issue.path.length === 0 && issue.code === "invalid_type") {
    return `Sandbox policy at ${sourceLabel} must be a JSON object.`;
  }

  const fieldLabel = `${sourceLabel}${formatIssuePath(issue.path)}`;
  if (issue.code === "unrecognized_keys" && issue.keys.length > 0) {
    return `Sandbox policy field ${fieldLabel}.${issue.keys[0]} is not supported.`;
  }
  if (issue.code === "invalid_type" && issue.path.length === 1) {
    return `Sandbox policy section ${fieldLabel} must be a JSON object.`;
  }
  if (issue.code === "invalid_type") {
    return `Sandbox policy field ${fieldLabel} ${issue.message}.`;
  }
  if (issue.code === "too_small") {
    return `Sandbox policy field ${fieldLabel} must be a positive number.`;
  }
  return `Sandbox policy field ${fieldLabel} ${issue.message}.`;
}

function formatIssuePath(pathSegments: readonly PropertyKey[]): string {
  let label = "";
  for (const segment of pathSegments) {
    if (typeof segment === "number") {
      label += `[${segment}]`;
      continue;
    }
    label += `.${String(segment)}`;
  }
  return label;
}

function isNodeError(err: unknown): err is NodeJS.ErrnoException {
  return err instanceof Error && "code" in err;
}

// Windows command-line construction and cmd.exe quoting for the MXC
// ProcessContainer backend.
//
// Security note: `command` and `args` originate from the agent/tool layer and
// are embedded into MXC's `process.commandLine`, which MXC passes to
// CreateProcessInSandbox -> cmd.exe *inside* the AppContainer sandbox. They
// never reach a host shell and cannot influence the base64 sandbox-policy
// payload (that travels on a separate argv flag to wxc-exec). Quoting here is
// about delivering arguments to the sandboxed program intact and preventing
// `%`-expansion / quote-breakout within the inner cmd.exe command line.

import { randomBytes } from "node:crypto";
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import path from "node:path";

function resolveCmdShell(): string {
  return process.env.ComSpec?.trim() || "cmd.exe";
}

// `cmd.exe /d /s /c "<line>"`: `/d` skips AutoRun, `/s` makes cmd.exe strip
// exactly one outer quote pair without re-parsing the inner line, which lets the
// wrapped script keep embedded `"` chars.
export function buildCommandLine(commandScript: string, args: readonly string[]): string {
  const shell = resolveCmdShell();
  if (args.length === 0) {
    return `${shell} /d /s /c "${commandScript}"`;
  }
  const escapedArgs = args.map(cmdArgumentEscape).join(" ");
  return `${shell} /d /s /c "${cmdArgumentEscape(commandScript)} ${escapedArgs}"`;
}

// Quote a single cmd.exe token: wrap in double quotes and neutralize the chars
// that would otherwise break out of the quoted token or trigger expansion:
// `"` -> `""` (cmd's in-quote quote escape), `%` -> `%%` (suppress env
// expansion), `^` -> `^^` (caret escape) so the token survives cmd parsing.
function cmdArgumentEscape(value: string): string {
  return `"${value.replaceAll("^", "^^").replaceAll("%", "%%").replaceAll(`"`, `""`)}"`;
}

// When positional args accompany a script, cmd.exe cannot reliably receive both
// an inline script and argv. Materialize the script as a temporary `.cmd` file
// (exclusive-create, owner-only mode) and run that file with the args appended.
// The caller must invoke `cleanup()` once the command has been built.
export function createWindowsCommandBridge(params: {
  args: readonly string[] | undefined;
  script: string;
  tempDir: string;
}): { command: string; cleanup: () => void } {
  if (!params.args || params.args.length === 0) {
    return { command: params.script, cleanup: () => {} };
  }

  const bridgeDir = mkdtempSync(path.join(params.tempDir, ".openclaw-mxc-cmd-"));
  const commandFile = path.join(bridgeDir, `${randomBytes(8).toString("hex")}.cmd`);
  try {
    writeFileSync(commandFile, `@echo off\r\n${params.script}`, { flag: "wx", mode: 0o600 });
  } catch (err) {
    rmSync(bridgeDir, { force: true, recursive: true });
    throw err;
  }
  return {
    command: commandFile,
    cleanup: () => rmSync(bridgeDir, { force: true, recursive: true }),
  };
}

// Windows process environment helpers for the MXC ProcessContainer backend.
//
// MXC's BaseContainerRunner treats a non-empty `process.env` as a replacement
// environment block for CreateProcessInSandbox: when present it replaces the
// entire default OS environment, so any required OS var (SystemRoot, COMSPEC, …)
// that is not listed is missing and cmd.exe fails with ERROR_ENVVAR_NOT_FOUND.
// These helpers build a minimal-but-complete Windows env block from required OS
// defaults plus caller overrides, and a separate launcher env for the spawn
// process itself.

// Env vars required by cmd.exe / CreateProcess inside the AppContainer. Caller
// overrides are layered on top; nothing else from the host environment leaks in.
const WINDOWS_PROCESS_ENV_DEFAULT_KEYS = [
  "SystemRoot",
  "SystemDrive",
  "ComSpec",
  "WINDIR",
  "PATH",
  "PATHEXT",
  "TEMP",
  "TMP",
  "USERPROFILE",
  "APPDATA",
  "LOCALAPPDATA",
  "ProgramData",
  "ALLUSERSPROFILE",
  "ProgramFiles",
  "ProgramFiles(x86)",
  "ProgramW6432",
  "CommonProgramFiles",
  "CommonProgramFiles(x86)",
  "CommonProgramW6432",
  "PUBLIC",
  "HOMEDRIVE",
  "HOMEPATH",
  "USERNAME",
  "USERDOMAIN",
  "COMPUTERNAME",
  "OS",
  "PROCESSOR_ARCHITECTURE",
  "PROCESSOR_IDENTIFIER",
  "PROCESSOR_LEVEL",
  "PROCESSOR_REVISION",
  "NUMBER_OF_PROCESSORS",
] as const;

// Env vars forwarded to the plugin-side Node launcher process (not the sandboxed
// child). The launcher only needs enough OS context to locate Node, temp dirs,
// and the user profile; the sandbox policy itself travels via the JSON payload.
const LAUNCHER_ENV_KEYS = [
  "SystemRoot",
  "SystemDrive",
  "ComSpec",
  "WINDIR",
  "PATH",
  "PATHEXT",
  "TEMP",
  "TMP",
  "USERPROFILE",
  "APPDATA",
  "LOCALAPPDATA",
  "ProgramFiles",
  "ProgramFiles(x86)",
  "ProgramW6432",
] as const;

function getEnvValueCaseInsensitive(env: NodeJS.ProcessEnv, key: string): string | undefined {
  const exact = env[key];
  if (exact !== undefined) {
    return exact;
  }
  const normalizedKey = key.toLowerCase();
  const match = Object.entries(env).find(
    ([candidate]) => candidate.toLowerCase() === normalizedKey,
  );
  return match?.[1];
}

function setCaseInsensitiveEnvEntry(
  entries: Map<string, { key: string; value: string }>,
  key: string,
  value: string | undefined,
): void {
  if (!key || key.includes("=") || value === undefined) {
    return;
  }
  entries.set(key.toLowerCase(), { key, value });
}

// Build the Windows replacement env block: required OS defaults first, then
// caller overrides (case-insensitively, since Windows env names are
// case-insensitive). Keys containing `=` are dropped so a malicious caller key
// cannot inject extra `NAME=VALUE` pairs into the block.
export function normalizeWindowsProcessEnvRecord(
  callerEnv: Record<string, string>,
  hostEnv: NodeJS.ProcessEnv = process.env,
): string[] {
  const entries = new Map<string, { key: string; value: string }>();
  for (const key of WINDOWS_PROCESS_ENV_DEFAULT_KEYS) {
    setCaseInsensitiveEnvEntry(entries, key, getEnvValueCaseInsensitive(hostEnv, key));
  }
  for (const [key, value] of Object.entries(callerEnv)) {
    setCaseInsensitiveEnvEntry(entries, key, value);
  }
  return [...entries.values()]
    .toSorted((a, b) => a.key.localeCompare(b.key))
    .map(({ key, value }) => `${key}=${value}`);
}

export function buildLauncherEnv(hostEnv: NodeJS.ProcessEnv = process.env): NodeJS.ProcessEnv {
  const env: NodeJS.ProcessEnv = {};
  for (const key of LAUNCHER_ENV_KEYS) {
    const value = getEnvValueCaseInsensitive(hostEnv, key);
    if (value !== undefined) {
      env[key] = value;
    }
  }
  return env;
}

import { lstatSync, realpathSync } from "node:fs";
import path from "node:path";
import { isPathInside } from "openclaw/plugin-sdk/file-access-runtime";

export type MxcWorkspaceAccess = "none" | "ro" | "rw";

export type MxcReadOnlySkillMount = {
  hostPath: string;
  containerPath: string;
};

const MATERIALIZED_SANDBOX_SKILLS_WORKSPACE_PARTS = [".openclaw", "sandbox-skills"] as const;

function containerJoin(root: string, ...parts: string[]): string {
  const normalizedRoot = root.endsWith("/") && root !== "/" ? root.slice(0, -1) : root;
  const suffix = parts
    .map((part) => part.replace(/^\/+|\/+$/g, ""))
    .filter(Boolean)
    .join("/");
  return suffix ? `${normalizedRoot}/${suffix}` : normalizedRoot;
}

function resolveMaterializedSandboxSkillsWorkspaceDir(rootDir: string): string {
  return path.join(rootDir, ...MATERIALIZED_SANDBOX_SKILLS_WORKSPACE_PARTS);
}

function isExistingMxcSkillMountSource(params: { rootDir: string; hostPath: string }): boolean {
  try {
    if (!lstatSync(params.hostPath).isDirectory()) {
      return false;
    }
    return isPathInside(
      realpathSync(path.resolve(params.rootDir)),
      realpathSync(path.resolve(params.hostPath)),
    );
  } catch {
    return false;
  }
}

export function resolveMxcReadOnlySkillMounts(params: {
  agentWorkspaceDir: string;
  skillsWorkspaceDir?: string;
  workdir: string;
  workspaceAccess: MxcWorkspaceAccess;
}): readonly MxcReadOnlySkillMount[] {
  if (params.workspaceAccess !== "rw") {
    return [];
  }

  const materializedSkillsWorkspaceDir =
    params.skillsWorkspaceDir ??
    resolveMaterializedSandboxSkillsWorkspaceDir(params.agentWorkspaceDir);
  const mounts = [
    {
      hostPath: path.join(params.agentWorkspaceDir, "skills"),
      containerPath: containerJoin(params.workdir, "skills"),
      rootDir: params.agentWorkspaceDir,
    },
    {
      hostPath: path.join(params.agentWorkspaceDir, ".agents", "skills"),
      containerPath: containerJoin(params.workdir, ".agents", "skills"),
      rootDir: params.agentWorkspaceDir,
    },
    {
      hostPath: path.join(materializedSkillsWorkspaceDir, "skills"),
      containerPath: containerJoin(
        params.workdir,
        ...MATERIALIZED_SANDBOX_SKILLS_WORKSPACE_PARTS,
        "skills",
      ),
      rootDir: materializedSkillsWorkspaceDir,
    },
  ];

  return mounts
    .filter((mount) =>
      isExistingMxcSkillMountSource({
        rootDir: mount.rootDir,
        hostPath: mount.hostPath,
      }),
    )
    .map(({ hostPath, containerPath }) => ({ hostPath, containerPath }));
}

