      expect(stringArrayField(noneFilesystem, "readonlyPaths")).toContain(
        path.resolve(sandboxWorkdir),
      );
      expect(stringArrayField(noneFilesystem, "readonlyPaths")).not.toContain(
        path.resolve(agentWorkspaceDir),
